// Choose N in [0, 512] so allocation stays <= 2048 bytes for 4-byte ints
int N = (int)(*FUZZ_PARAM(unsigned int) % 513u);

// Allocate at least one writable int to keep arr non-null even when N == 0
int alloc_elems = (N > 0) ? N : 1;
int *arr = new int[alloc_elems];

// Initialize arr[0..N-1] using fuzz data from a variable-size string buffer
// Avoid FUZZ_PARAM in a loop due to macro limitation; derive all data up-front
std::string seed = FUZZ_PARAM_STR();
const unsigned char *bytes = (const unsigned char *)seed.data();
size_t bytes_len = seed.size();
size_t ints_available = bytes_len / sizeof(int);
unsigned int base = *FUZZ_PARAM(unsigned int);      // base value for fallback filling
int delta = (int)((bytes_len % 97u) + 1u);          // small positive delta (1..97)

for (int i = 0; i < N; ++i) {
    if ((size_t)i < ints_available) {
        // Pack up to 4 bytes into an int in little-endian order to initialize from seed
        size_t off = (size_t)i * sizeof(int);
        unsigned int v = 0u;
        // Take exactly 4 bytes since ints_available guarantees availability
        v |= (unsigned int)bytes[off + 0] << 0;
        v |= (unsigned int)bytes[off + 1] << 8;
        v |= (unsigned int)bytes[off + 2] << 16;
        v |= (unsigned int)bytes[off + 3] << 24;
        arr[i] = (int)v;
    } else {
        // Fallback: deterministic pattern derived from base and delta; add sign variety
        int v = (int)(base + (unsigned int)(i * delta));
        if (((i & 1) != 0) && ((base & 1u) != 0)) { v = -v; }
        arr[i] = v;
    }
}

// Call the target function with a valid, non-null, writable buffer and non-negative N
int result = solution(arr, N);
(void)result; // Return semantics are unspecified; do not assert on it

// Caller-managed buffer: free locally since object is not persistent
delete[] arr;

